import React, { Fragment } from "react";
import Image from '../../assests/gana.jpg';
import classes from './HomePage.module.css';
 const HomePage=()=>{
    return(
        <Fragment>
            <header className={classes.header}>
                <h1> 🔱 शिव भोजनालय मे आपका स्वागत है 🔱  </h1>
               
            </header>
            <div>
               <img src={Image} alt></img>
            </div>
            <div>
                <h3>Click below to go to meals / नीचे Click करे 😊</h3>
                <button>CLICK ME</button>
            </div>
            <footer>

            </footer>
        </Fragment>
    )
 }
 export default HomePage;
